from pathlib import Path
R=Path(__file__).resolve().parents[1]
plans=[
 ('01-launch','PROOF Issue 01 — good ideas deserve good proofs','A publication about the decisions behind graphic design.','THE ANATOMY\nOF A PRINTED IDEA.','A closer look at how ideas move from observation to printed form.','READ THE ISSUE','hero-studio.webp', [('01 / THE OBSERVATION','How visual decisions start.'),('02 / THE COMPOSITION','What changes when the hierarchy changes.'),('03 / THE RELEASE','Why the final file still needs care.')]),
 ('02-process','PROOF — the details are the design','A look inside the creative and technical process.','BEHIND\nTHE FINAL IMAGE.','Explore the images, revisions and production choices that shape the project.','EXPLORE THE PROCESS','detail-spread.webp', [('ONE VISUAL SYSTEM','Adapted across print, social and email.'),('SOURCE & REVISION','Files and changes organized intentionally.'),('HONEST PRODUCTION','No imagined vendor approval or fabricated results.')])
]
for name,subject,pre,head,deck,cta,img,modules in plans:
 rows=''.join(f'<tr><td style="border-top:1px solid #b8b8aa;padding:20px 0;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td width="160" style="font:700 12px/18px Arial,sans-serif;vertical-align:top;letter-spacing:1px;color:#181917;">{lab}</td><td style="font:16px/23px Georgia,serif;color:#181917;">{desc}</td></tr></table></td></tr>' for lab,desc in modules)
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{subject} / PROOF</title><style>@media screen and (max-width:620px){{.body-width{{width:100%!important;max-width:100%!important}}.gutter{{padding-left:24px!important;padding-right:24px!important}}.headline{{font-size:39px!important;line-height:42px!important}}.action{{display:block!important;text-align:center!important}}}}</style></head><body style="margin:0;padding:0;background:#d9d9d3;"><div style="display:none;font-size:1px;max-height:0;opacity:0;overflow:hidden;mso-hide:all;">{pre}&nbsp;&zwnj;&nbsp;&zwnj;</div><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#d9d9d3;"><tr><td align="center" style="padding:22px 8px 45px;"><!--[if mso]><table role="presentation" width="600" align="center" cellpadding="0" cellspacing="0"><tr><td><![endif]--><table role="presentation" class="body-width" width="100%" cellpadding="0" cellspacing="0" style="background:#f2efe8;width:100%;max-width:600px;"><tr><td class="gutter" style="padding:26px 35px 21px;"><table role="presentation" width="100%"><tr><td style="font:bold 32px Arial,sans-serif;letter-spacing:-2px;color:#181917;">PROOF<span style="color:#ff542d;">.</span></td><td align="right" style="font:700 10px/16px Arial,sans-serif;letter-spacing:1px;color:#181917;">DESIGN / PUBLICATION<br>ISSUE 01</td></tr></table></td></tr><tr><td><img src="../assets/{img}" alt="Photographic design-studio still life with printed pages and creative-production details" width="600" style="display:block;max-width:100%;width:100%;height:auto;border:0;"></td></tr><tr><td class="gutter" style="padding:35px 35px 30px;"><p style="font:bold 12px Arial,sans-serif;letter-spacing:1.5px;margin:0 0 17px;color:#ff542d;">PROOF / AN INDEPENDENT DESIGN STUDY</p><h1 class="headline" style="font:bold 48px/50px Arial,Helvetica,sans-serif;letter-spacing:-2px;color:#181917;margin:0 0 24px;">{head.replace(chr(10),'<br>')}</h1><p style="font:19px/28px Georgia,serif;color:#252725;margin:0 0 30px;">{deck}</p><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background:#181917;"><a class="action" href="../index.html#publication" style="display:inline-block;padding:17px 22px;font:bold 13px Arial,sans-serif;text-decoration:none;background:#181917;color:#f2efe8;">{cta} →</a></td></tr></table></td></tr><tr><td class="gutter" style="padding:15px 35px 25px;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0">{rows}</table></td></tr><tr><td class="gutter" style="background:#1b1c1a;padding:30px 35px 36px;color:#f2efe8;"><p style="font:italic 26px/32px Georgia,serif;margin:0 0 21px;">Good ideas deserve good proofs.</p><p style="font:12px/20px Arial,sans-serif;margin:0;color:#b7bbaf;">Speculative portfolio email. PROOF is fictional. No live sender, audience, conversion data or functional unsubscribe system is represented. For a real mailing, replace relative image links with authorized hosted assets and add sender information, opt-out controls and email-client testing.</p></td></tr></table><!--[if mso]></td></tr></table><![endif]--></td></tr></table></body></html>'''
 (R/'emails'/f'{name}.html').write_text(html)
 (R/'emails'/f'{name}.txt').write_text(f'Subject: {subject}\nPreheader: {pre}\n\n{head.replace(chr(10),chr(32))}\n\n{deck}\n\n'+ '\n'.join(k+': '+v for k,v in modules)+'\n\nConcept portfolio only. No real distribution, subscriber data or unsubscribe integration.\n')
print('Wrote 2 standalone HTML emails with text alternatives')
